class MyBlock(nn.Module):
    def __init__(self):
        super().__init__()
        self.register_buffer('running_mean', torch.zeros(10))
        self.lin = nn.Linear(10, 10)
    def forward(self, x):
        self.running_mean = 0.9 * self.running_mean + 0.1 * x.mean(dim=0)
        return self.lin(x)

block = MyBlock()
print(block.state_dict().keys())

