class MyReLU(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        ctx.save_for_backward(x)
        return x.clamp(min=0)
    @staticmethod
    def backward(ctx, grad_output):
        x, = ctx.saved_tensors
        grad_input = grad_output.clone()
        grad_input[x < 0] = 0
        return grad_input

x = torch.tensor([-2., 0., 3.], requires_grad=True)
out = MyReLU.apply(x)
out.sum().backward()
print(x.grad)  # [0., 0., 1.]
